import { useEffect, useState } from "react";
import { ArrowRight, Lock } from "lucide-react";
import { useTranslation } from "@/i18n";
import { LocalizedLink } from "@/utils/localizedRoute";
import { hasCompleteStoredAdminApiKey } from "@/utils/adminKeyAuth";
import { getProfile, type Profile } from "@/utils/branding-shared";

function isDistributorProfile(profile: Profile | null) {
  return (
    profile?.role === "ambassador" ||
    profile?.role === "broker" ||
    profile?.brokerId === "ambassador"
  );
}

export function useAdminFeatureAccess() {
  const { t } = useTranslation();
  const [profile, setProfile] = useState<Profile | null>(() => getProfile());
  const [hasAdminApiKey, setHasAdminApiKey] = useState(() =>
    hasCompleteStoredAdminApiKey()
  );

  useEffect(() => {
    function refreshAdminAccess() {
      setProfile(getProfile());
      setHasAdminApiKey(hasCompleteStoredAdminApiKey());
    }

    refreshAdminAccess();
    window.addEventListener("authChanged", refreshAdminAccess);
    window.addEventListener("profileUpdated", refreshAdminAccess);
    window.addEventListener("storage", refreshAdminAccess);
    return () => {
      window.removeEventListener("authChanged", refreshAdminAccess);
      window.removeEventListener("profileUpdated", refreshAdminAccess);
      window.removeEventListener("storage", refreshAdminAccess);
    };
  }, []);

  const hasAdminFeatureAccess =
    hasAdminApiKey &&
    (isDistributorProfile(profile) || profile?.adminRegistered === true);
  const adminLockCta = !profile?.builderName
    ? {
        href: "/home",
        label: t("adminFeatureLock.goToDashboard"),
      }
    : !isDistributorProfile(profile) && profile.adminRegistered !== true
      ? {
          href: "/admin-setup",
          label: t("adminFeatureLock.completeAdminSetup"),
        }
      : {
          href: "/settings/api-keys",
          label: t("adminFeatureLock.createApiKey"),
        };

  return {
    profile,
    hasAdminApiKey,
    hasAdminFeatureAccess,
    lockProps: {
      title: t("adminFeatureLock.title"),
      description: t("adminFeatureLock.description"),
      ctaHref: adminLockCta.href,
      ctaLabel: adminLockCta.label,
    },
  };
}

export function AdminFeatureLock({
  title,
  description,
  ctaHref,
  ctaLabel,
}: {
  title: string;
  description: string;
  ctaHref: string;
  ctaLabel: string;
}) {
  return (
    <section className="rounded-xl border border-dashed border-(--line-subtle) bg-(--bg-surface-secondary) p-10 text-center">
      <div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-full bg-(--bg-hover) text-(--fg-secondary)">
        <Lock className="h-6 w-6" />
      </div>
      <h4 className="mb-1 text-base font-medium text-(--fg-primary)">
        {title}
      </h4>
      <p className="mx-auto mb-5 max-w-md text-sm leading-6 text-(--fg-secondary)">
        {description}
      </p>
      <LocalizedLink
        to={ctaHref}
        className="inline-flex items-center gap-2 rounded-full px-5 pb-[11px] pt-2.5 text-sm font-medium leading-none text-(--fg-primary) transition-opacity hover:opacity-90"
        style={{ background: "var(--bg-brand-grad)" }}
      >
        {ctaLabel}
        <ArrowRight className="h-4 w-4" />
      </LocalizedLink>
    </section>
  );
}
